\node at (11,\y) {$\s$};\node at (63.5,\y) {$\f$};
\pgfmathtruncatemacro{\groups}{floor(\f/5)}
\pgfmathtruncatemacro{\rest}{mod(\f,5)}
\ifnum\groups>0
\foreach \g in {1,...,\groups}{\pgfmathsetmacro{\xx}{25+(\g-1)*11}\foreach \i in {0,1,2,3}{\draw[black,line width=0.4pt] (\xx+2*\i,\y-2.5)--(\xx+2*\i,\y+2.5);}\draw[black,line width=0.4pt] (\xx-1,\y-2)--(\xx+7,\y+2);}
\fi
\ifnum\rest>0
\foreach \i in {1,...,\rest}{\draw[black,line width=0.4pt] ({25+11*\groups+2*(\i-1)},{\y-2.5})--({25+11*\groups+2*(\i-1)},{\y+2.5});}
\fi}
\node at (63.5,-68) {$\Sigma f=40$};
